/// <summary>
/// find record
/// </summary>
/// <param name = "_firma">company</param>
/// <param name = "_child">allience id</param>
/// <param name = "_forUpdate">for update</param>
/// <returns>KCS_TOSTable record</returns>
static KCS_TOSTable findChild(DataAreaId _firma, KCS_BOSAllianceID _child, boolean _forUpdate = false)
{
    KCS_TOSTable    lKCS_TOSTable;

    lKCS_TOSTable.selectForUpdate(_forUpdate);

    if (_child)
    {
        select lKCS_TOSTable
            where lKCS_TOSTable.DataAreaId == _firma
                && lKCS_TOSTable.TosId == _child;
    }

    return lKCS_TOSTable;
}

/// <summary>
/// recursive function call
/// </summary>
/// <param name = "_KCS_TOSTableCustTmpLocal"></param>
/// <returns>all customers to alliance</returns>
private KCS_TOSTableCustTmp loopTos(KCS_TOSTableCustTmp _KCS_TOSTableCustTmpLocal)
{
    custTable custTableLocal;
    KCS_TOSTable tOSTableParent;

    while select custTableLocal
            where custTableLocal.KCS_TOSId == this.TosId
    {
        _KCS_TOSTableCustTmpLocal.CustAccount = custTableLocal.AccountNum;
        _KCS_TOSTableCustTmpLocal.Name = custTableLocal.name();
        _KCS_TOSTableCustTmpLocal.TOSId = custTableLocal.KCS_TOSId;
        _KCS_TOSTableCustTmpLocal.StructureStr = KCS_TOSTableHistory::getStructureStr(_KCS_TOSTableCustTmpLocal.TOSId);
        _KCS_TOSTableCustTmpLocal.insert();
    }

    while select tOSTableParent
            where tOSTableParent.ParentTosId == this.TosId
    {
        _KCS_TOSTableCustTmpLocal = tOSTableParent.loopTos(_KCS_TOSTableCustTmpLocal);

    }

    return _KCS_TOSTableCustTmpLocal;
}

/// <summary>
/// gets all customers for an alliance
/// </summary>
/// <returns>customer records</returns>
public KCS_TOSTableCustTmp buildTOSTableCustTmp()
{
    KCS_TOSTableCustTmp KCS_TOSTableCustTmpLocal;

    KCS_TOSTableCustTmpLocal = this.loopTos(KCS_TOSTableCustTmpLocal);

    return KCS_TOSTableCustTmpLocal;

}
